/* @lc app=leetcode id=3646 lang=kotlin */ class Solution { fun pm(c: IntArray): List<String> = if (c.all { it == 0 }) listOf("") else (1..9).filter { c[it] > 0 }.flatMap { d -> pm(c.copyOf().also { it[d]-- }).map { s -> "$d$s" } } fun specialPalindrome(n: Long): Long = (1 until 512).filter { m -> (1..9).filter { m shr (it - 1) and 1 == 1 }.let { ds -> ds.count { it % 2 == 1 } <= 1 && ds.sum() <= 17 } }.flatMap { m -> (1..9).filter { m shr (it - 1) and 1 == 1 }.let { ds -> pm(IntArray(10).also { c -> ds.forEach { c[it] = it / 2 } }).map { h -> h + (ds.firstOrNull { it % 2 == 1 }?.toString() ?: "") + h.reversed() } } }.map { it.toLong() }.filter { it > n }.min() }